getUsername->running.set(true);
fileOsRelease->reload();
const std::string textOsRelease = fileOsRelease->text();

// Extract the friendly name (PRETTY_NAME field, fallback to NAME)
const auto prettyNameMatch = js::match(textOsRelease, js::Regex("^PRETTY_NAME=\"(.+?)\"", "m"));
const auto nameMatch = js::match(textOsRelease, js::Regex("^NAME=\"(.+?)\"", "m"));
distroName.set(prettyNameMatch ? (*prettyNameMatch)[1]
                               : (nameMatch ? js::trim(js::replace((*nameMatch)[1], js::Regex("Linux", "i"), ""))
                                            : std::string("Unknown")));

// Extract the ID
const auto idMatch = js::match(textOsRelease, js::Regex("^ID=\"?(.+?)\"?$", "m"));
distroId.set(idMatch ? (*idMatch)[1] : std::string("unknown"));

// Extract additional URLs and logo
const auto homeUrlMatch = js::match(textOsRelease, js::Regex("^HOME_URL=\"(.+?)\"", "m"));
homeUrl.set(homeUrlMatch ? (*homeUrlMatch)[1] : std::string(""));
const auto documentationUrlMatch = js::match(textOsRelease, js::Regex("^DOCUMENTATION_URL=\"(.+?)\"", "m"));
documentationUrl.set(documentationUrlMatch ? (*documentationUrlMatch)[1] : std::string(""));
const auto supportUrlMatch = js::match(textOsRelease, js::Regex("^SUPPORT_URL=\"(.+?)\"", "m"));
supportUrl.set(supportUrlMatch ? (*supportUrlMatch)[1] : std::string(""));
const auto bugReportUrlMatch = js::match(textOsRelease, js::Regex("^BUG_REPORT_URL=\"(.+?)\"", "m"));
bugReportUrl.set(bugReportUrlMatch ? (*bugReportUrlMatch)[1] : std::string(""));
const auto privacyPolicyUrlMatch = js::match(textOsRelease, js::Regex("^PRIVACY_POLICY_URL=\"(.+?)\"", "m"));
privacyPolicyUrl.set(privacyPolicyUrlMatch ? (*privacyPolicyUrlMatch)[1] : std::string(""));
const auto logoFieldMatch = js::match(textOsRelease, js::Regex("^LOGO=\"?(.+?)\"?$", "m"));
logo.set(logoFieldMatch ? (*logoFieldMatch)[1] : std::string(""));

// Update the distroIcon property based on distroId
const std::string id = distroId.get();
if (id == "artix" || id == "arch") {
  distroIcon.set("arch-symbolic");
} else if (id == "manjaro") {
  distroIcon.set("manjaro-symbolic");
} else if (id == "endeavouros") {
  distroIcon.set("endeavouros-symbolic");
} else if (id == "cachyos") {
  distroIcon.set("cachyos-symbolic");
} else if (id == "nixos") {
  distroIcon.set("nixos-symbolic");
} else if (id == "fedora") {
  distroIcon.set("fedora-symbolic");
} else if (id == "linuxmint" || id == "ubuntu" || id == "zorin" || id == "popos") {
  distroIcon.set("ubuntu-symbolic");
} else if (id == "debian" || id == "raspbian" || id == "kali") {
  distroIcon.set("debian-symbolic");
} else if (id == "funtoo" || id == "gentoo") {
  distroIcon.set("gentoo-symbolic");
} else {
  distroIcon.set("linux-symbolic");
}
if (js::includes(js::toLowerCase(textOsRelease), "nyarch")) {
  distroIcon.set("nyarch-symbolic");
}

if (js::trim(logo.get()).empty()) {
  logo.set(distroIcon.get());
}

